"""本体模型：解析结果的只读视图。

模型内部以不可变集合保存数据，所有读取接口返回新的不可变序列，
不会修改已解析的数据，因此同一模型可重复读取且结果稳定。
"""

from __future__ import annotations

import itertools
from typing import Iterator, Optional, Tuple

from .errors import OntologyError
from .query import QueryResult, run_query

_VARIABLE_PREFIX = "?"

_EXPLICIT_KIND = "explicit"
_RULE_KIND = "rule"


def _is_variable(value: str) -> bool:
    return value.startswith(_VARIABLE_PREFIX)


class Triple(tuple):
    """一条三元组 (subject, predicate, object)，按字典序可比较。"""

    __slots__ = ()

    def __new__(cls, subject: str, predicate: str, object_: str) -> "Triple":
        return super().__new__(cls, (subject, predicate, object_))

    @property
    def subject(self) -> str:
        return self[0]

    @property
    def predicate(self) -> str:
        return self[1]

    @property
    def object(self) -> str:
        return self[2]

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return f"Triple({self[0]!r}, {self[1]!r}, {self[2]!r})"


class DerivedTriple:
    """一条推理结论：三元组 + 来源规则 id。"""

    __slots__ = ("_triple", "_rule_id")

    def __init__(self, triple: Triple, rule_id) -> None:
        self._triple = triple
        self._rule_id = rule_id

    @property
    def triple(self) -> Triple:
        return self._triple

    @property
    def subject(self) -> str:
        return self._triple.subject

    @property
    def predicate(self) -> str:
        return self._triple.predicate

    @property
    def object(self) -> str:
        return self._triple.object

    @property
    def rule_id(self):
        return self._rule_id

    def __iter__(self) -> Iterator:
        return iter((self._triple, self._rule_id))

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, DerivedTriple)
            and self._triple == other._triple
            and self._rule_id == other._rule_id
        )

    def __hash__(self) -> int:
        return hash((self._triple, self._rule_id))

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return f"DerivedTriple({self._triple!r}, rule_id={self._rule_id!r})"


class Proof:
    """一条三元组的证明树节点（只读快照）。

    - kind 为 "explicit"：triple 是输入中的显式事实，ruleId 为 None，
      premises 为空元组；
    - kind 为 "rule"：triple 由规则 ruleId 经具体常量替换后推出，
      premises 按该规则 if 模式的原顺序给出各前提的证明节点，
      沿 premises 可一直追到显式叶子。
    所有公开属性只读；相等性按 kind/triple/ruleId/premises 结构比较。
    """

    __slots__ = ("_kind", "_triple", "_rule_id", "_premises")

    def __init__(self, kind: str, triple: Triple, rule_id, premises) -> None:
        self._kind = kind
        self._triple = triple
        self._rule_id = rule_id
        self._premises = tuple(premises)

    @property
    def kind(self) -> str:
        """证明种类："explicit" 或 "rule"。"""
        return self._kind

    @property
    def triple(self) -> Triple:
        """本节点证明的三元组。"""
        return self._triple

    @property
    def ruleId(self):
        """推出该三元组的规则 id（保留原始字符串或整数）；显式事实为 None。"""
        return self._rule_id

    @property
    def premises(self) -> Tuple["Proof", ...]:
        """前提证明节点元组，按规则 if 模式的原顺序排列。"""
        return self._premises

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, Proof)
            and self._kind == other._kind
            and self._triple == other._triple
            and self._rule_id == other._rule_id
            and self._premises == other._premises
        )

    def __hash__(self) -> int:
        return hash((self._kind, self._triple, self._rule_id, self._premises))

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return (
            f"Proof(kind={self._kind!r}, triple={self._triple!r}, "
            f"ruleId={self._rule_id!r}, premises={self._premises!r})"
        )


def _leaf_count(proof: Proof) -> int:
    """证明长度：树中显式叶子的数量。"""
    if proof.kind == _EXPLICIT_KIND:
        return 1
    return sum(_leaf_count(premise) for premise in proof.premises)


def _proof_sort_key(proof: Proof):
    """稳定排序键：kind、ruleId 的字符串形式、节点 triple、premises 顺序。"""
    return (
        proof.kind,
        str(proof.ruleId),
        proof.triple,
        tuple(_proof_sort_key(premise) for premise in proof.premises),
    )


def _unify_then(pattern, triple: Triple):
    """把 then 模式与基三元组对齐，返回变量→常量绑定；不一致时返回 None。"""
    s, p, o = pattern
    if p != triple.predicate:
        return None
    binding = {}
    for term, value in ((s, triple.subject), (o, triple.object)):
        if _is_variable(term):
            if term in binding:
                if binding[term] != value:
                    return None
            else:
                binding[term] = value
        elif term != value:
            return None
    return binding


def _instantiate(pattern, binding) -> Triple:
    """按绑定把三元组模式替换为基三元组（模式中的变量均已绑定）。"""
    s, p, o = pattern
    return Triple(
        binding.get(s, s) if _is_variable(s) else s,
        p,
        binding.get(o, o) if _is_variable(o) else o,
    )


class OntologyModel:
    """解析与推理完成后的本体模型。

    - explicit_triples：显式三元组，按 (主语, 谓语, 宾语) 字典序排列。
    - derived_triples：推理结论，同样按字典序排列，每条带来源规则 id。
    - entails(s, p, o)：判断单条三元组是否被蕴含（显式或推理得出）。
    - explain(s, p, o)：给出该三元组的全部最短完整证明（Proof 元组）。
    - declared_properties：本体中已声明的属性名（查询谓语/属性路径据此校验）。
    所有读取接口均返回新对象，不改变模型内部数据。
    """

    __slots__ = ("_explicit", "_derived", "_facts", "_source", "_properties", "_rules")

    def __init__(self, explicit, derived, properties=frozenset(), rules=()) -> None:
        # explicit / derived: dict[Triple, rule_id 或 None]
        # rules: (rule_id, if 模式, then 模式) 元组序列，模式为 (s, p, o) 字符串三元组
        self._explicit = frozenset(explicit)
        self._derived = frozenset(
            DerivedTriple(triple, rule_id) for triple, rule_id in derived.items()
        )
        self._facts = frozenset(explicit) | frozenset(derived)
        self._source = dict(derived)
        self._properties = frozenset(properties)
        self._rules = tuple(
            (
                rule_id,
                tuple(tuple(pattern) for pattern in if_patterns),
                tuple(tuple(pattern) for pattern in then_patterns),
            )
            for rule_id, if_patterns, then_patterns in rules
        )

    @property
    def explicit_triples(self) -> Tuple[Triple, ...]:
        """显式三元组，按字典序稳定排列。"""
        return tuple(sorted(self._explicit))

    @property
    def derived_triples(self) -> Tuple[DerivedTriple, ...]:
        """推理结论（含来源规则 id），按三元组字典序稳定排列。"""
        return tuple(sorted(self._derived, key=lambda d: (d.triple, str(d.rule_id))))

    @property
    def triples(self) -> Tuple[Triple, ...]:
        """全部三元组（显式 + 推理），按字典序稳定排列。"""
        return tuple(sorted(self._facts))

    @property
    def declared_properties(self) -> Tuple[str, ...]:
        """本体中已声明的属性名，按字典序稳定排列。"""
        return tuple(sorted(self._properties))

    def entails(self, subject: str, predicate: str, object_: str) -> bool:
        """判断 (subject, predicate, object_) 是否被当前模型蕴含。"""
        return Triple(subject, predicate, object_) in self._facts

    def source_rule(self, subject: str, predicate: str, object_: str) -> Optional[object]:
        """返回推理出该三元组的规则 id；显式或未知三元组返回 None。"""
        return self._source.get(Triple(subject, predicate, object_))

    def explain(self, subject: str, predicate: str, object_) -> Tuple[Proof, ...]:
        """返回 (subject, predicate, object_) 的全部最短完整证明。

        - 显式事实：返回恰一个 kind 为 "explicit" 的证明（即使它同时也能
          被规则推出，显式证明优先）；
        - 推理结论：返回全部显式叶子数最少的完整证明；规则有多个 then
          或不同替换能推出目标时全部保留，按 kind、ruleId 的字符串形式、
          节点 triple 和 premises 顺序稳定排列，重复树去重；
        - 未被蕴含的三元组：返回空元组。
        证明不依赖推理循环（成环规则上有限结束）。subject、predicate、
        object 任一不是字符串时抛出 OntologyError。
        """
        for position, (name, value) in enumerate(
            (("subject", subject), ("predicate", predicate), ("object", object_)),
            start=1,
        ):
            if not isinstance(value, str):
                raise OntologyError(
                    f"explain 的第 {position} 个参数（{name}）必须是字符串，"
                    f"收到 {value!r}"
                )
        goal = Triple(subject, predicate, object_)
        if goal in self._explicit:
            return (Proof(_EXPLICIT_KIND, goal, None, ()),)
        if goal not in self._facts:
            return ()
        proofs = self._prove(goal, frozenset())
        if not proofs:  # pragma: no cover - 推理结论必有证明，此处仅作防御
            return ()
        best = min(_leaf_count(proof) for proof in proofs)
        chosen = [proof for proof in proofs if _leaf_count(proof) == best]
        unique = list(dict.fromkeys(chosen))
        unique.sort(key=_proof_sort_key)
        return tuple(unique)

    # ---------- 证明枚举（后向链接，按路径阻断循环） ----------

    def _prove(self, goal: Triple, blocked: frozenset) -> list:
        """枚举 goal 的全部无环证明（未按叶子数过滤）。

        blocked 为当前根到此节点路径上已出现的目标三元组；前提落入
        blocked 的替换被丢弃，因此成环规则上证明枚举必然有限结束，
        且不会返回依赖循环的证明。
        """
        if goal in self._explicit:
            return [Proof(_EXPLICIT_KIND, goal, None, ())]
        if goal not in self._facts:
            return []
        blocked = blocked | {goal}
        fact_list = sorted(self._facts)
        proofs = []
        for rule_id, if_patterns, then_patterns in self._rules:
            for then in then_patterns:
                partial = _unify_then(then, goal)
                if partial is None:
                    continue
                for binding in self._match(if_patterns, fact_list, partial):
                    premises = tuple(
                        _instantiate(pattern, binding) for pattern in if_patterns
                    )
                    if any(triple in blocked for triple in premises):
                        continue
                    options = []
                    for triple in premises:
                        sub = self._prove(triple, blocked)
                        if not sub:
                            break
                        options.append(sub)
                    else:
                        for combo in itertools.product(*options):
                            proofs.append(Proof(_RULE_KIND, goal, rule_id, combo))
        return proofs

    @staticmethod
    def _match(patterns, fact_list, initial) -> list:
        """从给定部分绑定出发，对 if 模式按序做连接匹配（与推理同序）。"""
        bindings = [dict(initial)]
        for s, p, o in patterns:
            next_bindings = []
            for binding in bindings:
                for fact in fact_list:
                    if fact.predicate != p:
                        continue
                    if _is_variable(s):
                        if s in binding and fact.subject != binding[s]:
                            continue
                    elif fact.subject != s:
                        continue
                    extended = dict(binding)
                    if _is_variable(s):
                        extended[s] = fact.subject
                    if _is_variable(o):
                        if o in extended and fact.object != extended[o]:
                            continue
                    elif fact.object != o:
                        continue
                    if _is_variable(o):
                        extended[o] = fact.object
                    next_bindings.append(extended)
            bindings = next_bindings
            if not bindings:
                break
        return bindings

    def query(self, text: str) -> QueryResult:
        """执行 SPARQL 风格 SELECT 查询，在显式与推理三元组上匹配。

        例如 SELECT ?x ?y WHERE { ?x knows ?y . ?y likes ?z }；
        模式体中还可以出现 OPTIONAL { ... }（左连接，无匹配时块内变量未绑定）、
        FILTER ( 表达式 )（BOUND/!BOUND 与 =/!= 比较，多个 FILTER 逻辑与）
        以及 { ... } UNION { ... }（多个花括号分支取并集，分支内仅含三元组
        模式，连续 UNION 从左到右结合）。
        谓语位置除常量属性名外还接受属性路径，只作用于本模型的
        explicit + derived 三元组并集：^p 逆向、a/b 序列复合、a|b 取并集、
        p?/p*/p+ 分别为零或一次/零或多次/一次或多次，圆括号只用于分组，
        路径中的属性名必须已声明；p?/p* 的零次分支只连接三元组中实际出现
        过的节点，p+ 在环状数据上也会有限结束。OPTIONAL 与 UNION 块内同样
        可以使用属性路径；FILTER 不把路径当作比较操作数。
        查询不修改模型，重复执行结果一致。词法或语法错误抛出 OntologyError。
        """
        return run_query(self, text)

"""OntologyEngine：解析 JSON 本体定义并做规则前向链推理。

输入约定（UTF-8 文本形式的 JSON）：

- 根对象必须包含 classes、properties、individuals、triples、rules 五个字段，
  可选包含 consistency 字段。
- classes / properties / individuals：字符串名称数组；名称在三个数组的并集内不得重复。
- triples：显式三元组数组，每项为 {"subject": ..., "predicate": ..., "object": ...}，
  三个值均为字符串，不允许变量；predicate 必须是已声明属性。
- rules：规则数组，每项为 {"id": ..., "if": [...], "then": [...]}；
  id 为字符串或整数且不得重复；if/then 为三元组模式数组，结构与 triples 相同，
  主语/宾语可以是以 "?" 开头的变量；then 中出现的变量必须在 if 中被绑定。
- consistency：可选对象，恰含 classMembershipPredicate、disjointClasses、
  functionalProperties 三个字段。

推理：对规则做前向链推理直至不动点。结论按 (主语, 谓语, 宾语) 字典序输出，
同一三元组被多条规则推出时保留最先推出它的规则 id；显式三元组优先于推理结论。

一致性诊断在结构校验与不动点推理完成后进行：同一个体同时属于一条
disjointClasses 约束中的两个类、或在一条 functionalProperties 约束的属性上
有两个不同取值，parse 抛出 InconsistencyError 且不返回模型；diagnose 不抛
异常，改为返回 ValidationReport（is_consistent 为 False、model 为 None、
diagnostics 按与异常冲突行相同的顺序列出全部两两冲突）。
"""

from __future__ import annotations

import json
from typing import Dict, List, Optional, Tuple

from .errors import InconsistencyError, OntologyError
from .model import OntologyModel, Triple
from .report import ValidationReport

_ROOT_FIELDS = ("classes", "properties", "individuals", "triples", "rules")
_TRIPLE_KEYS = frozenset({"subject", "predicate", "object"})
_RULE_KEYS = frozenset({"id", "if", "then"})
_VARIABLE_PREFIX = "?"

_CONSISTENCY_KEYS = frozenset(
    {"classMembershipPredicate", "disjointClasses", "functionalProperties"}
)
_DISJOINT_KEYS = frozenset({"id", "classes"})
_FUNCTIONAL_KEYS = frozenset({"id", "property"})

# 冲突类型的稳定排序：disjointClasses 在 functionalProperties 之前。
_CONFLICT_DISJOINT = 0
_CONFLICT_FUNCTIONAL = 1


def _is_variable(value: str) -> bool:
    return value.startswith(_VARIABLE_PREFIX)


def _is_id(value) -> bool:
    """consistency 约束 id：非空字符串或整数（bool 不算）。"""
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    return isinstance(value, str) and bool(value)


class _RulePattern:
    """一条编译后的规则：id + if 模式列表 + then 模式列表。"""

    __slots__ = ("rule_id", "if_patterns", "then_patterns")

    def __init__(self, rule_id, if_patterns, then_patterns) -> None:
        self.rule_id = rule_id
        self.if_patterns = if_patterns  # List[Tuple[str, str, str]]
        self.then_patterns = then_patterns


class _DisjointConstraint:
    __slots__ = ("constraint_id", "classes")

    def __init__(self, constraint_id, classes: Tuple[str, ...]) -> None:
        self.constraint_id = constraint_id
        self.classes = tuple(classes)


class _FunctionalConstraint:
    __slots__ = ("constraint_id", "property")

    def __init__(self, constraint_id, property_: str) -> None:
        self.constraint_id = constraint_id
        self.property = property_


class _Consistency:
    __slots__ = ("membership_predicate", "disjoint", "functional")

    def __init__(self, membership_predicate, disjoint, functional) -> None:
        self.membership_predicate = membership_predicate
        self.disjoint = disjoint
        self.functional = functional


class OntologyEngine:
    """公开入口：解析本体定义文本，返回可重复读取的 OntologyModel。"""

    def parse(self, text) -> OntologyModel:
        """解析 UTF-8 文本形式的 JSON 本体定义并完成前向链推理。

        发现语义冲突时抛出 InconsistencyError，不返回模型；结构与输入错误
        抛出 OntologyError。需要结构化诊断时使用 diagnose。
        """
        model, conflicts = self._build(text)
        if conflicts is not None:
            lines = [f"本体一致性诊断发现 {len(conflicts)} 处冲突："]
            lines.extend(conflict["message"] for conflict in conflicts)
            raise InconsistencyError("\n".join(lines))
        return model

    def diagnose(self, text) -> ValidationReport:
        """与 parse 相同的输入与结构校验，语义冲突以 ValidationReport 返回。

        输入类型、JSON、UTF-8 或结构非法仍抛 OntologyError（消息与 parse
        完全一致）。无冲突时报告的 is_consistent 为 True、model 为推理后的
        OntologyModel、diagnostics 为空元组；有冲突时 is_consistent 为 False、
        model 为 None、diagnostics 列出全部两两冲突，顺序与 parse 的
        InconsistencyError 冲突行一致。
        """
        model, conflicts = self._build(text)
        if conflicts is not None:
            return ValidationReport(False, None, conflicts)
        return ValidationReport(True, model, ())

    def __call__(self, text) -> OntologyModel:
        return self.parse(text)

    # ---------- 解析、推理与一致性检查的共同流程 ----------

    def _build(self, text) -> Tuple[OntologyModel, Optional[List[dict]]]:
        """返回 (模型, 冲突列表)；无冲突时冲突列表为 None。

        结构非法在抛出 OntologyError 前终止，与历史 parse 行为一致；
        一致性检查不通过时模型不返回（调用方只取冲突列表）。
        """
        data = self._load_json(text)
        self._validate_root(data)
        classes, properties, individuals = self._collect_names(data)
        explicit = self._parse_explicit_triples(data["triples"], properties)
        rules = self._parse_rules(data["rules"], properties)
        consistency = self._parse_consistency(data, classes, properties)
        derived = self._forward_chain(explicit, rules)
        conflicts: Optional[List[dict]] = None
        if consistency is not None:
            found = self._collect_conflicts(
                explicit, derived, consistency, classes, individuals
            )
            if found:
                conflicts = found
        model = OntologyModel(
            explicit,
            derived,
            properties,
            rules=tuple(
                (rule.rule_id, tuple(rule.if_patterns), tuple(rule.then_patterns))
                for rule in rules
            ),
        )
        return model, conflicts

    # ---------- 解析与校验 ----------

    def _load_json(self, text):
        if isinstance(text, (bytes, bytearray)):
            try:
                text = bytes(text).decode("utf-8")
            except UnicodeDecodeError as exc:
                raise OntologyError(f"输入不是合法的 UTF-8 文本: {exc}") from exc
        if not isinstance(text, str):
            raise OntologyError(
                f"输入必须是 str 或 bytes 类型的 JSON 文本，收到 {type(text).__name__}"
            )
        try:
            return json.loads(text)
        except json.JSONDecodeError as exc:
            raise OntologyError(
                f"JSON 语法错误: 第 {exc.lineno} 行第 {exc.colno} 列: {exc.msg}"
            ) from exc

    def _validate_root(self, data) -> None:
        if not isinstance(data, dict):
            raise OntologyError(
                f"根节点必须是 JSON 对象，收到 {type(data).__name__}"
            )
        for field in _ROOT_FIELDS:
            if field not in data:
                raise OntologyError(f"根对象缺少必需字段 {field!r}")
            if not isinstance(data[field], list):
                raise OntologyError(
                    f"字段 {field!r} 必须是数组，收到 {type(data[field]).__name__}"
                )

    def _collect_names(self, data) -> Tuple[frozenset, frozenset, frozenset]:
        """校验 classes/properties/individuals，返回三个已声明名称集合。"""
        seen = {}
        for field in ("classes", "properties", "individuals"):
            for index, name in enumerate(data[field]):
                if not isinstance(name, str) or not name:
                    raise OntologyError(
                        f"字段 {field!r} 第 {index} 项必须是非空字符串，"
                        f"收到 {name!r}"
                    )
                if name in seen:
                    raise OntologyError(
                        f"名称 {name!r} 重复声明（出现在 {seen[name]!r} 与 {field!r}）"
                    )
                seen[name] = field
        return (
            frozenset(data["classes"]),
            frozenset(data["properties"]),
            frozenset(data["individuals"]),
        )

    def _check_triple_shape(self, item, where: str) -> dict:
        if not isinstance(item, dict):
            raise OntologyError(
                f"{where} 必须是包含 subject/predicate/object 的对象，"
                f"收到 {item!r}"
            )
        keys = set(item)
        if keys != _TRIPLE_KEYS:
            missing = _TRIPLE_KEYS - keys
            extra = keys - _TRIPLE_KEYS
            detail = []
            if missing:
                detail.append("缺少 " + ", ".join(sorted(missing)))
            if extra:
                detail.append("多出 " + ", ".join(sorted(extra)))
            raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")
        for key in ("subject", "predicate", "object"):
            if not isinstance(item[key], str) or not item[key]:
                raise OntologyError(
                    f"{where} 的 {key!r} 必须是非空字符串，收到 {item[key]!r}"
                )
        return item

    def _parse_explicit_triples(self, triples, properties) -> List[Triple]:
        result: List[Triple] = []
        seen = set()
        for index, item in enumerate(triples):
            where = f"triples[{index}]"
            self._check_triple_shape(item, where)
            s, p, o = item["subject"], item["predicate"], item["object"]
            for key, value in (("subject", s), ("predicate", p), ("object", o)):
                if _is_variable(value):
                    raise OntologyError(
                        f"{where} 的 {key!r} 不允许使用变量 {value!r}（显式三元组必须是基三元组）"
                    )
            if p not in properties:
                raise OntologyError(
                    f"{where} 引用了未声明的属性 {p!r}"
                )
            triple = Triple(s, p, o)
            if triple not in seen:
                seen.add(triple)
                result.append(triple)
        return result

    def _parse_rules(self, rules, properties) -> List[_RulePattern]:
        parsed: List[_RulePattern] = []
        seen_ids = set()
        for index, item in enumerate(rules):
            where = f"rules[{index}]"
            if not isinstance(item, dict):
                raise OntologyError(
                    f"{where} 必须是包含 id/if/then 的对象，收到 {item!r}"
                )
            keys = set(item)
            if keys != _RULE_KEYS:
                missing = _RULE_KEYS - keys
                extra = keys - _RULE_KEYS
                detail = []
                if missing:
                    detail.append("缺少 " + ", ".join(sorted(missing)))
                if extra:
                    detail.append("多出 " + ", ".join(sorted(extra)))
                raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")

            rule_id = item["id"]
            if isinstance(rule_id, bool) or not isinstance(rule_id, (str, int)):
                raise OntologyError(
                    f"{where} 的 id 必须是字符串或整数，收到 {rule_id!r}"
                )
            if isinstance(rule_id, str) and not rule_id:
                raise OntologyError(f"{where} 的 id 不能为空字符串")
            if rule_id in seen_ids:
                raise OntologyError(f"规则 id {rule_id!r} 重复（{where}）")
            seen_ids.add(rule_id)
            where = f"规则 {rule_id!r}"

            for field in ("if", "then"):
                if not isinstance(item[field], list):
                    raise OntologyError(
                        f"{where} 的 {field!r} 必须是三元组数组，"
                        f"收到 {type(item[field]).__name__}"
                    )

            if_patterns = self._parse_patterns(item["if"], properties, where, "if")
            then_patterns = self._parse_patterns(item["then"], properties, where, "then")

            bound = set()
            for s, _, o in if_patterns:
                if _is_variable(s):
                    bound.add(s)
                if _is_variable(o):
                    bound.add(o)
            for pos, (s, _, o) in enumerate(then_patterns):
                for key, value in (("subject", s), ("object", o)):
                    if _is_variable(value) and value not in bound:
                        raise OntologyError(
                            f"{where} 的 then[{pos}] 中变量 {value!r} 未在 if 中绑定"
                        )
            parsed.append(_RulePattern(rule_id, if_patterns, then_patterns))
        return parsed

    def _parse_patterns(self, patterns, properties, where: str, field: str):
        result = []
        for pos, item in enumerate(patterns):
            loc = f"{where} 的 {field}[{pos}]"
            self._check_triple_shape(item, loc)
            s, p, o = item["subject"], item["predicate"], item["object"]
            if _is_variable(p):
                raise OntologyError(
                    f"{loc} 的谓语不允许是变量 {p!r}（谓语只能是已声明属性）"
                )
            if p not in properties:
                raise OntologyError(f"{loc} 引用了未声明的属性 {p!r}")
            result.append((s, p, o))
        return result

    # ---------- consistency 结构校验 ----------

    def _parse_consistency(self, data, classes: frozenset, properties: frozenset):
        if "consistency" not in data:
            return None
        root = data["consistency"]
        if not isinstance(root, dict):
            raise OntologyError(
                "字段 'consistency' 必须是对象，"
                f"收到 {type(root).__name__}"
            )
        keys = set(root)
        if keys != _CONSISTENCY_KEYS:
            missing = _CONSISTENCY_KEYS - keys
            extra = keys - _CONSISTENCY_KEYS
            detail = []
            if missing:
                detail.append("缺少 " + ", ".join(sorted(missing)))
            if extra:
                detail.append("多出 " + ", ".join(sorted(extra)))
            raise OntologyError(f"consistency 结构不合法（{'; '.join(detail)}）")

        predicate = root["classMembershipPredicate"]
        if not isinstance(predicate, str) or not predicate:
            raise OntologyError(
                "consistency['classMembershipPredicate'] 必须是非空字符串，"
                f"收到 {predicate!r}"
            )
        if predicate not in properties:
            raise OntologyError(
                "consistency['classMembershipPredicate'] 引用了未声明的属性 "
                f"{predicate!r}"
            )

        seen_ids = {}
        disjoint = self._parse_disjoint(root["disjointClasses"], classes, seen_ids)
        functional = self._parse_functional(
            root["functionalProperties"], properties, seen_ids
        )
        return _Consistency(predicate, disjoint, functional)

    def _claim_constraint_id(self, constraint_id, where: str, seen_ids: dict) -> None:
        if not _is_id(constraint_id):
            raise OntologyError(
                f"{where}['id'] 必须是非空字符串或整数，收到 {constraint_id!r}"
            )
        if constraint_id in seen_ids:
            raise OntologyError(
                f"consistency 约束 id {constraint_id!r} 重复"
                f"（{seen_ids[constraint_id]} 与 {where}）"
            )
        seen_ids[constraint_id] = where

    def _parse_disjoint(self, items, classes: frozenset, seen_ids: dict):
        if not isinstance(items, list):
            raise OntologyError(
                "consistency['disjointClasses'] 必须是对象数组，"
                f"收到 {type(items).__name__}"
            )
        result = []
        for index, item in enumerate(items):
            where = f"consistency['disjointClasses'][{index}]"
            if not isinstance(item, dict):
                raise OntologyError(
                    f"{where} 必须是包含 id/classes 的对象，收到 {item!r}"
                )
            keys = set(item)
            if keys != _DISJOINT_KEYS:
                missing = _DISJOINT_KEYS - keys
                extra = keys - _DISJOINT_KEYS
                detail = []
                if missing:
                    detail.append("缺少 " + ", ".join(sorted(missing)))
                if extra:
                    detail.append("多出 " + ", ".join(sorted(extra)))
                raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")

            self._claim_constraint_id(item["id"], where, seen_ids)

            names = item["classes"]
            if not isinstance(names, list):
                raise OntologyError(
                    f"{where}['classes'] 必须是字符串数组，"
                    f"收到 {type(names).__name__}"
                )
            for pos, name in enumerate(names):
                if not isinstance(name, str) or not name:
                    raise OntologyError(
                        f"{where}['classes'][{pos}] 必须是非空字符串，收到 {name!r}"
                    )
            if len(names) < 2:
                raise OntologyError(
                    f"{where}['classes'] 至少需要列出两个类，收到 {len(names)} 个"
                )
            local_seen = set()
            for name in names:
                if name in local_seen:
                    raise OntologyError(
                        f"{where}['classes'] 中类名 {name!r} 重复"
                    )
                local_seen.add(name)
            for name in names:
                if name not in classes:
                    raise OntologyError(
                        f"{where}['classes'] 引用了未声明的类 {name!r}"
                    )
            result.append(_DisjointConstraint(item["id"], names))
        return result

    def _parse_functional(self, items, properties: frozenset, seen_ids: dict):
        if not isinstance(items, list):
            raise OntologyError(
                "consistency['functionalProperties'] 必须是对象数组，"
                f"收到 {type(items).__name__}"
            )
        result = []
        for index, item in enumerate(items):
            where = f"consistency['functionalProperties'][{index}]"
            if not isinstance(item, dict):
                raise OntologyError(
                    f"{where} 必须是包含 id/property 的对象，收到 {item!r}"
                )
            keys = set(item)
            if keys != _FUNCTIONAL_KEYS:
                missing = _FUNCTIONAL_KEYS - keys
                extra = keys - _FUNCTIONAL_KEYS
                detail = []
                if missing:
                    detail.append("缺少 " + ", ".join(sorted(missing)))
                if extra:
                    detail.append("多出 " + ", ".join(sorted(extra)))
                raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")

            self._claim_constraint_id(item["id"], where, seen_ids)

            property_ = item["property"]
            if not isinstance(property_, str) or not property_:
                raise OntologyError(
                    f"{where}['property'] 必须是非空字符串，收到 {property_!r}"
                )
            if property_ not in properties:
                raise OntologyError(
                    f"{where}['property'] 引用了未声明的属性 {property_!r}"
                )
            result.append(_FunctionalConstraint(item["id"], property_))
        return result

    # ---------- 前向链推理 ----------

    def _forward_chain(self, explicit: List[Triple], rules: List[_RulePattern]) -> Dict[Triple, object]:
        """返回 dict[Triple, rule_id]：仅包含推理结论（不含显式三元组）。"""
        facts: Dict[Triple, Optional[object]] = {t: None for t in explicit}
        while True:
            changed = False
            # 每轮按排序后的事实列表匹配，保证绑定枚举顺序确定。
            fact_list = sorted(facts)
            for rule in rules:
                for binding in self._match(rule.if_patterns, fact_list):
                    for pattern in rule.then_patterns:
                        triple = Triple(
                            binding.get(pattern[0], pattern[0]),
                            pattern[1],
                            binding.get(pattern[2], pattern[2]),
                        )
                        if triple not in facts:
                            facts[triple] = rule.rule_id
                            changed = True
            if not changed:
                break
        return {t: rid for t, rid in facts.items() if rid is not None}

    def _match(self, patterns, fact_list) -> List[Dict[str, str]]:
        """对 if 模式按序做连接匹配，返回所有满足的变量绑定。"""
        bindings: List[Dict[str, str]] = [{}]
        for s, p, o in patterns:
            next_bindings: List[Dict[str, str]] = []
            for binding in bindings:
                for fact in fact_list:
                    if fact.predicate != p:
                        continue
                    if _is_variable(s):
                        if s in binding and fact.subject != binding[s]:
                            continue
                    elif fact.subject != s:
                        continue
                    extended = dict(binding)
                    if _is_variable(s):
                        extended[s] = fact.subject
                    # 宾语变量需与同一模式内已绑定的主语变量保持一致（如 (?x, p, ?x)）。
                    if _is_variable(o):
                        if o in extended and fact.object != extended[o]:
                            continue
                    elif fact.object != o:
                        continue
                    if _is_variable(o):
                        extended[o] = fact.object
                    next_bindings.append(extended)
            bindings = next_bindings
            if not bindings:
                break
        return bindings

    # ---------- 一致性诊断 ----------

    def _collect_conflicts(
        self,
        explicit: List[Triple],
        derived: Dict[Triple, object],
        consistency: _Consistency,
        classes: frozenset,
        individuals: frozenset,
    ) -> List[dict]:
        """收集全部两两冲突，按与 InconsistencyError 相同的顺序排列。"""
        # 全部事实的来源表：显式事实为 None，推理结论为来源规则 id。
        fact_source: Dict[Triple, Optional[object]] = {t: None for t in explicit}
        fact_source.update(derived)

        membership = self._membership_facts(
            fact_source, consistency.membership_predicate, classes, individuals
        )
        # 各收集器返回 (排序键, 诊断字典) 元组列表。
        conflicts = []
        conflicts.extend(
            self._disjoint_conflicts(membership, consistency.disjoint)
        )
        conflicts.extend(
            self._functional_conflicts(fact_source, consistency.functional)
        )
        if not conflicts:
            return []

        # 按约束 id 的字符串表示、冲突类型、subject、冲突条目字典序排列。
        conflicts.sort(key=lambda item: item[0])
        return [diagnostic for _, diagnostic in conflicts]

    def _membership_facts(
        self,
        fact_source: Dict[Triple, Optional[object]],
        predicate: str,
        classes: frozenset,
        individuals: frozenset,
    ) -> Dict[Tuple[str, str], Optional[object]]:
        """收集 {(subject, class): 来源}：仅保留已声明个体与已声明类上的类成员事实。"""
        membership: Dict[Tuple[str, str], Optional[object]] = {}
        for triple, source in fact_source.items():
            if triple.predicate != predicate:
                continue
            if triple.subject not in individuals:
                continue
            if triple.object not in classes:
                continue
            membership.setdefault((triple.subject, triple.object), source)
        return membership

    def _disjoint_conflicts(self, membership, constraints):
        conflicts = []
        for constraint in constraints:
            names = sorted(constraint.classes)
            holders: Dict[str, List[str]] = {}
            for subject, class_name in membership:
                if class_name in names:
                    holders.setdefault(subject, []).append(class_name)
            for subject, owned in holders.items():
                if len(owned) < 2:
                    continue
                owned_set = frozenset(owned)
                for pos, first in enumerate(names):
                    if first not in owned_set:
                        continue
                    for second in names[pos + 1 :]:
                        if second not in owned_set:
                            continue
                        src1 = membership[(subject, first)]
                        src2 = membership[(subject, second)]
                        message = (
                            f"[disjointClasses id={constraint.constraint_id!r}] "
                            f"个体 {subject!r} 同时属于互斥类 {first!r} 与 {second!r}："
                            f"{first!r} 为{self._describe_source(src1)}；"
                            f"{second!r} 为{self._describe_source(src2)}"
                        )
                        diagnostic = {
                            "kind": "disjointClassMembership",
                            "constraintId": constraint.constraint_id,
                            "subject": subject,
                            "evidence": (
                                {"class": first, "source": self._source_info(src1)},
                                {"class": second, "source": self._source_info(src2)},
                            ),
                            "message": message,
                        }
                        key = (
                            str(constraint.constraint_id),
                            _CONFLICT_DISJOINT,
                            subject,
                            first,
                            second,
                        )
                        conflicts.append((key, diagnostic))
        return conflicts

    def _functional_conflicts(self, fact_source: Dict[Triple, Optional[object]], constraints):
        conflicts = []
        for constraint in constraints:
            property_ = constraint.property
            # subject -> {object: 来源}
            by_subject: Dict[str, Dict[str, Optional[object]]] = {}
            for triple, source in fact_source.items():
                if triple.predicate != property_:
                    continue
                by_subject.setdefault(triple.subject, {}).setdefault(
                    triple.object, source
                )
            for subject, objects in by_subject.items():
                if len(objects) < 2:
                    continue
                ordered = sorted(objects)
                for pos, first in enumerate(ordered):
                    for second in ordered[pos + 1 :]:
                        src1 = objects[first]
                        src2 = objects[second]
                        message = (
                            f"[functionalProperties id={constraint.constraint_id!r}] "
                            f"个体 {subject!r} 在函数型属性 {property_!r} 上有两个不同取值 "
                            f"{first!r} 与 {second!r}："
                            f"{first!r} 为{self._describe_source(src1)}；"
                            f"{second!r} 为{self._describe_source(src2)}"
                        )
                        diagnostic = {
                            "kind": "functionalPropertyValue",
                            "constraintId": constraint.constraint_id,
                            "subject": subject,
                            "evidence": (
                                {"object": first, "source": self._source_info(src1)},
                                {"object": second, "source": self._source_info(src2)},
                            ),
                            "message": message,
                        }
                        key = (
                            str(constraint.constraint_id),
                            _CONFLICT_FUNCTIONAL,
                            subject,
                            property_,
                            first,
                            second,
                        )
                        conflicts.append((key, diagnostic))
        return conflicts

    @staticmethod
    def _source_info(source) -> dict:
        """结构化事实来源：显式事实为 {'kind': 'explicit'}；推理事实带原始规则 id。"""
        if source is None:
            return {"kind": "explicit"}
        return {"kind": "derived", "ruleId": source}

    @staticmethod
    def _describe_source(source) -> str:
        if source is None:
            return "显式事实（explicit_triples）"
        return f"推理结论（derived_triples，source_rule={source!r}）"

"""结构化一致性诊断报告：OntologyEngine.diagnose 的返回值。

- is_consistent：本体是否通过全部一致性约束。
- model：一致时为推理完成后的 OntologyModel；存在冲突时为 None。
- diagnostics：诊断元组，无冲突时为空元组；每条诊断为字段固定的字典，
  读取接口返回新的副本，不会改变报告内部数据，同一输入重复诊断结果稳定。
"""

from __future__ import annotations

from typing import Any, Iterator, Optional, Tuple

from .model import OntologyModel


def _freeze(value: Any) -> Any:
    """把诊断中的 list/dict 复制为 tuple/dict 快照，隔离调用方的后续修改。"""
    if isinstance(value, dict):
        return {key: _freeze(val) for key, val in value.items()}
    if isinstance(value, (list, tuple)):
        return tuple(_freeze(item) for item in value)
    return value


def _model_signature(model: Optional[OntologyModel]):
    """模型按其显式/推理内容比较；None 只与 None 相等。"""
    if model is None:
        return None
    return model.explicit_triples, model.derived_triples


class ValidationReport:
    """本体一致性诊断的只读结果。

    一致时 model 为推理后的 OntologyModel、diagnostics 为空元组；
    不一致时 model 为 None、diagnostics 列出全部两两冲突，顺序与
    parse 抛出的 InconsistencyError 中的冲突行一致。
    """

    __slots__ = ("_is_consistent", "_model", "_diagnostics")

    def __init__(
        self,
        is_consistent: bool,
        model: Optional[OntologyModel],
        diagnostics,
    ) -> None:
        self._is_consistent = bool(is_consistent)
        self._model = model
        self._diagnostics: Tuple[dict, ...] = tuple(
            _freeze(diagnostic) for diagnostic in diagnostics
        )

    @property
    def is_consistent(self) -> bool:
        return self._is_consistent

    @property
    def model(self) -> Optional[OntologyModel]:
        """一致时为推理后的 OntologyModel；不一致时为 None。"""
        return self._model

    @property
    def diagnostics(self) -> Tuple[dict, ...]:
        """诊断字典的新元组；重复读取返回内容相同的独立副本。"""
        return tuple(_freeze(diagnostic) for diagnostic in self._diagnostics)

    def __len__(self) -> int:
        return len(self._diagnostics)

    def __iter__(self) -> Iterator[dict]:
        return iter(self.diagnostics)

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, ValidationReport):
            return NotImplemented
        return (
            self._is_consistent == other._is_consistent
            and _model_signature(self._model) == _model_signature(other._model)
            and self._diagnostics == other._diagnostics
        )

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return (
            f"ValidationReport(is_consistent={self._is_consistent!r}, "
            f"model={'None' if self._model is None else 'OntologyModel(...)'}, "
            f"diagnostics={self._diagnostics!r})"
        )

import json
import unittest

from onto_reason import (
    InconsistencyError,
    OntologyEngine,
    OntologyError,
    QueryResult,
    Triple,
    ValidationReport,
)


def make_doc(**overrides):
    doc = {
        "classes": ["Person"],
        "properties": ["knows", "likes", "friendOf"],
        "individuals": ["alice", "bob", "carol"],
        "triples": [
            {"subject": "alice", "predicate": "knows", "object": "bob"},
            {"subject": "bob", "predicate": "knows", "object": "carol"},
        ],
        "rules": [],
    }
    doc.update(overrides)
    return doc


def parse(doc):
    return OntologyEngine().parse(json.dumps(doc))


class ParseAndValidateTests(unittest.TestCase):
    def test_json_syntax_error(self):
        with self.assertRaises(OntologyError) as ctx:
            OntologyEngine().parse("{not json")
        self.assertIn("JSON", str(ctx.exception))

    def test_non_utf8_bytes(self):
        with self.assertRaises(OntologyError):
            OntologyEngine().parse(b"\xff\xfe{}")

    def test_utf8_bytes_accepted(self):
        model = OntologyEngine().parse(json.dumps(make_doc()).encode("utf-8"))
        self.assertEqual(len(model.explicit_triples), 2)

    def test_root_must_be_object(self):
        with self.assertRaises(OntologyError):
            OntologyEngine().parse("[1, 2]")

    def test_missing_root_field(self):
        doc = make_doc()
        del doc["rules"]
        with self.assertRaises(OntologyError) as ctx:
            parse(doc)
        self.assertIn("rules", str(ctx.exception))

    def test_root_field_wrong_type(self):
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(classes="Person"))
        self.assertIn("classes", str(ctx.exception))

    def test_duplicate_name_within_array(self):
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(individuals=["alice", "bob", "alice"]))
        self.assertIn("alice", str(ctx.exception))

    def test_duplicate_name_across_arrays(self):
        with self.assertRaises(OntologyError):
            parse(make_doc(classes=["Person"], individuals=["Person"]))

    def test_explicit_triple_bad_shape(self):
        bad = {"subject": "alice", "predicate": "knows"}
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(triples=[bad]))
        self.assertIn("triples[0]", str(ctx.exception))

    def test_explicit_triple_undeclared_property(self):
        bad = {"subject": "alice", "predicate": "hates", "object": "bob"}
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(triples=[bad]))
        self.assertIn("hates", str(ctx.exception))
        self.assertIn("triples[0]", str(ctx.exception))

    def test_explicit_triple_rejects_variable(self):
        bad = {"subject": "?x", "predicate": "knows", "object": "bob"}
